// Generated by secure-by-design v0.1.0 for OWASP-aligned security headers.
// Maps to: ISO 27001 A.8.26 / A.8.28, NIST SSDF PW.9.
// Reads from ../../privacy-security-manifest.yaml.
// Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
// Docs: docs/scaffolds/security-headers.md

import type { Request, Response, NextFunction } from 'express';

export interface SecurityHeaderOptions {
  // Set false in dev if a stricter CSP breaks hot reload.
  enableStrictCsp?: boolean;
  // Set true if you serve embeddable widgets and need a specific frame ancestor.
  allowedFrameAncestors?: string[];
  // Domains your app legitimately fetches from (CSP connect-src additions).
  additionalConnectSrc?: string[];
}

const DEFAULT_OPTIONS: Required<Omit<SecurityHeaderOptions, 'allowedFrameAncestors' | 'additionalConnectSrc'>> & SecurityHeaderOptions = {
  enableStrictCsp: true,
};

export function securityHeaders(opts: SecurityHeaderOptions = {}) {
  const o = { ...DEFAULT_OPTIONS, ...opts };

  const connectSrc = ["'self'", ...(o.additionalConnectSrc ?? [])].join(' ');
  const frameAncestors = (o.allowedFrameAncestors && o.allowedFrameAncestors.length > 0)
    ? o.allowedFrameAncestors.join(' ')
    : "'none'";

  const csp = o.enableStrictCsp
    ? [
        "default-src 'self'",
        `connect-src ${connectSrc}`,
        "img-src 'self' data:",
        "style-src 'self' 'unsafe-inline'", // tighten in your CSP review
        "script-src 'self'",
        "object-src 'none'",
        "base-uri 'self'",
        "form-action 'self'",
        `frame-ancestors ${frameAncestors}`,
        "upgrade-insecure-requests",
      ].join('; ')
    : null;

  return (_req: Request, res: Response, next: NextFunction): void => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', frameAncestors === "'none'" ? 'DENY' : 'SAMEORIGIN');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
    res.setHeader('Strict-Transport-Security', 'max-age=63072000; includeSubDomains; preload');
    res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
    res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
    if (csp) res.setHeader('Content-Security-Policy', csp);
    // Do NOT set Server / X-Powered-By — disable them in your app config.
    next();
  };
}
